// ssrf.ts
type FetchLike = (url: string | URL, init?: RequestInit) => Promise<Response>;

export const guardedFetch: FetchLike = async (url, init = {}) => {
  let cur = String(url);
  for (let hop = 0; hop <= MAX_HOPS; hop++) {
    await assertAllowed(cur);                              // DNS-resolve + allowlist, every hop
    const res = await fetch(cur, { ...init, redirect: 'manual' }); // redirect AFTER the spread
    if (![301, 302, 303, 307, 308].includes(res.status)) return res;
    const loc = res.headers.get('location');
    if (!loc) return res;
    await res.body?.cancel();
    cur = new URL(loc, cur).href;
    if (res.status === 303) init = { ...init, method: 'GET', body: undefined };
  }
  throw new Error('too many redirects');
};

// injection point — identical for both transports:
new StreamableHTTPClientTransport(new URL(upstream), { fetch: guardedFetch });
new SSEClientTransport(new URL(upstream), { fetch: guardedFetch });
